import{j as s}from"./index-DbFL10Cm.js";const t="/images/stock/",a={P03:{file:"stem-teacher-student-experiment.jpg",alt:"A teacher and a young student doing a science experiment together at a whiteboard"},P04:{file:"robotics-students-building.jpg",alt:"Three students building and testing a small red robot together at a table"},P05:{file:"ai-students-laptops-teacher.jpg",alt:"Two students working on a laptop while a teacher looks on in a classroom"},P06:{file:"iot-student-soldering-circuit.jpg",alt:"A student soldering an electronic circuit board at a workbench"},P07:{file:"coding-students-computers.jpg",alt:"Students working at computers in a classroom"},P08:{file:"lab-children-assembling-parts.jpg",alt:"Children assembling parts of a project together at a table in a learning lab"},P09:{file:"programme-teacher-robotics-class.jpg",alt:"A teacher guiding students who are building red robots in a classroom"},P10:{file:"college-computer-lab.jpg",alt:"A student working at a computer in a college computer lab"},P11:{file:"partnership-handshake-chalkboard.jpg",alt:"A teacher and a student shaking hands in front of a chalkboard"},P12:{file:"region-school-computer-room.jpg",alt:"A classroom full of school students working at computers"}},r=e=>{const o=a[e];return o?{...o,src:t+o.file,width:1200,height:800}:null},h=({pageId:e})=>{const o=r(e);return o?s.jsxs("figure",{className:"max-w-4xl mx-auto",children:[s.jsx("img",{src:o.src,alt:o.alt,width:o.width,height:o.height,loading:"lazy",decoding:"async",className:"w-full h-auto rounded-2xl shadow-xl"}),s.jsx("figcaption",{className:"mt-3 text-sm text-gray-600 text-center",children:"Illustrative stock photograph, not one of our sessions."})]}):null},n="/case-studies",d={P03:{pageId:"P03",path:"/stem-workshops-schools-indore",title:"STEM Workshops for Schools in Indore | Builds Your Mind",description:"Hands-on STEM workshops for schools in Indore. Students build, test and solve real problems. Invite us for a workshop or kick-off session.",h1:"STEM Workshops for Schools in Indore",badge:"For Schools in Indore",intro:["Builds Your Mind runs STEM workshops for schools in Indore. Students build, test and solve real problems instead of only reading about them. Every session is planned around the class groups you give us and run at your institution.","If you are looking for a STEM workshop in Indore that fits your timetable, start with one session. Many schools then move to a set of technology workshops for schools across the year."],button:"Invite Us for a Workshop",altAction:{label:"See all workshops",to:"#other-workshops"},sections:[{heading:"What Students Learn",body:"Activities are practical from the first minute. Students work in small groups and explain their results at the end.",items:["Practical science and engineering, built by hand","How to plan an idea and test whether it works","How to find and fix a problem when something fails","Explaining their work to the rest of the class"]},{heading:"How a Workshop Runs",body:"We agree the topic, the class group and the date with your coordinator, then bring the activity plans and materials.",items:["You share the class groups and the time available","We plan activities that fit that time","We run the session at your institution","Your teachers stay involved throughout"]},{heading:"Suitable Class Groups",body:"Sessions are matched to the age of the group rather than run as one fixed programme.",items:["Primary classes: guided builds with clear steps","Middle school: longer builds with testing and iteration","Senior school: open problems with more student decisions"]},{heading:"From Workshop to Annual Programme",body:"A single workshop is a good way to see how students respond. From there, schools usually choose one of three routes.",items:["One workshop: a kick-off or an activity day","A set of workshops across the term","A full-year programme with a planned sequence"]}],photoSpots:[{label:"Real workshop photo needed",detail:"Students building and testing a STEM activity during a session at a school in Indore. Use a photo from a real, completed workshop, with the school's permission. Do not use a stock image here."}],faqs:[{q:"Who are the STEM workshops for?",a:"Schools in Indore and the surrounding area, for primary, middle and senior class groups. Sessions are planned around the group you give us."},{q:"How long is a workshop?",a:"The length is agreed with your institution when you enquire, based on the class groups and the time you have available."},{q:"Do students need any prior experience?",a:"No. Activities start from the beginning, and students work in small groups so nobody is left behind."},{q:"What do you need from the school?",a:"A class group, a date, and a space where students can build and test. We plan the rest with your coordinator."},{q:"How do we book a workshop?",a:"Send your institution details through the enquiry page. A programme advisor will get back to you to plan the session."}],related:["P04"],keywords:["STEM Workshops for Schools in Indore","STEM Workshop Indore","Technology Workshops for Schools"]},P04:{pageId:"P04",path:"/robotics-workshops-schools-indore",title:"Robotics Workshops for Schools in Indore | Builds Your Mind",description:"Practical robotics workshops for schools in Indore and Madhya Pradesh. Students build and test robots. Ask about a workshop or a full programme.",h1:"Robotics Workshops for Schools in Indore",badge:"Build, Test, Fix",intro:["Builds Your Mind runs practical robotics workshops for schools in Indore and across Madhya Pradesh. Students assemble a robot, test it, and then work out why it does what it does.","This is robotics education for schools in Indore built around doing: every group finishes the session with something they have made and tested themselves. For a robotics workshop in Indore, tell us the class group and the date you have in mind."],button:"Enquire About a Robotics Workshop",altAction:{label:"See all workshops",to:"#other-workshops"},sections:[{heading:"What Students Build",body:"Groups build a working robot and then improve it. The goal is not a perfect first attempt but a tested one.",items:["A simple robot that moves on command","A build that reacts to its surroundings","Small changes to see how behaviour changes","A short demonstration for the class"]},{heading:"Workshop Format",body:"A robotics workshop for schools works best as a hands-on session with small groups and a clear task.",items:["Short introduction to the parts and what they do","Group build with support from our trainers","Testing and fixing, repeated until it works","Wrap-up where each group explains their robot"]},{heading:"One-Time Workshop or Structured Programme",body:"You can book a single session or plan robotics training for schools across the year.",items:["One-time workshop: a kick-off or an activity day","A term of sessions: build on what was learned before","A full programme: a planned sequence through the year"]},{heading:"Photos from Real Workshops",body:"We publish photographs from real, completed workshops, with the school's permission. The photo at the top of this page is an illustrative stock photograph, not one of our sessions.",photoSlots:2}],photoSpots:[{label:"Real workshop photo needed",detail:"A robot built and tested by students during a robotics workshop. Use a photo from a real session, with the school's permission. Do not use a stock image here."},{label:"Second real workshop photo needed",detail:"Students testing their robot on the floor during a session, working as a group. Use a real photo with permission. Do not use a stock image here."}],faqs:[{q:"Which class groups can take part?",a:"Primary, middle and senior groups, with the build and the task matched to the age of the students."},{q:"Do students need to know robotics already?",a:"No. Every build starts from the parts and what they do, so the session works for beginners."},{q:"Can you run robotics training for schools across several sessions?",a:"Yes. A one-time workshop is the usual starting point, and schools often continue with a set of sessions or a full programme."},{q:"Do you run workshops outside Indore?",a:"Our work covers Indore and Madhya Pradesh. Tell us your city and dates on the enquiry page and we will confirm what we can plan."},{q:"How do we enquire?",a:"Share your institution details on the enquiry page. A programme advisor will get back to you to plan the workshop."}],related:["P03"],keywords:["Robotics Workshops for Schools in Indore","Robotics Education for Schools in Indore","Robotics Workshop in Indore","Robotics Workshop for Schools","Robotics Training for Schools"]},P05:{pageId:"P05",path:"/ai-workshops-schools",title:"AI Workshops for Schools | Builds Your Mind",description:"Age-appropriate AI learning sessions for schools. Students explore how AI works through simple, practical activities. Enquire for your school.",h1:"AI Workshops for Schools",badge:"Age-Appropriate",intro:["Builds Your Mind runs age-appropriate AI workshops for schools. Students explore how AI works through simple, practical activities, without needing any prior experience.","An AI workshop for schools should give students something they can actually follow: what AI is, where they already meet it, and what it can and cannot do. That is how we plan every session — a practical introduction to AI education for schools, not a lecture."],button:"Enquire About an AI Workshop",altAction:{label:"See all workshops",to:"#other-workshops"},sections:[{heading:"What Students Explore",body:"Activities are built around things students already see, so the ideas land quickly.",items:["What AI is, in plain language","How a system learns from examples","Where AI already appears in everyday tools","What AI does well, and where it gets things wrong"]},{heading:"Age Groups",body:"The same ideas are pitched differently for different ages.",items:["Primary classes: recognising AI in everyday tools","Middle school: how examples shape what a system learns","Senior school: using AI tools, and checking their output"]},{heading:"Sample Activities",body:"Practical tasks, done in small groups, with discussion afterwards.",items:["Sorting and labelling examples to see how learning works","Spotting the mistake in an AI answer","Designing a simple task a machine could help with"]},{heading:"Safe and Responsible Use of AI",body:"Students leave with simple habits for using AI tools sensibly.",items:["Never share personal details with an AI tool","Always check an answer before using it","Say clearly when AI helped produce your work","Know when to ask a teacher instead"]}],photoSpots:[{label:"Real workshop photo needed",detail:"Students taking part in an AI workshop activity. Use a photo from a real session, with the school's permission. Do not use a stock image here."}],faqs:[{q:"Is AI suitable for younger students?",a:"Yes. The sessions are age-appropriate, and younger groups work with everyday examples rather than technical detail."},{q:"Do students need computers for an AI workshop?",a:"Not for every activity. Some tasks are done away from screens. If a session needs devices, we tell you in advance so your school can arrange them."},{q:"How is the session planned?",a:"We agree the class group and the time available, then plan the activities to fit. Session length is agreed when you enquire."},{q:"Does this teach students to use AI for homework?",a:"It teaches students to understand what AI is and to use it responsibly — including setting work honestly and checking what a tool produces."},{q:"How do we enquire for our school?",a:"Send your institution details through the enquiry page and a programme advisor will get back to you."}],related:["P03"],keywords:["AI Workshop for Schools","AI Education for Schools"]},P06:{pageId:"P06",path:"/iot-workshops-schools",title:"IoT Workshops for Schools | Builds Your Mind",description:"Hands-on IoT workshops for schools covering sensors, connected devices and small projects. Contact Builds Your Mind to plan a session.",h1:"IoT Workshops for Schools",badge:"Sensors & Devices",intro:["Builds Your Mind runs hands-on IoT workshops for schools. Students work with sensors and connected devices, then build a small project that responds to something real.","An IoT workshop for schools is a good way to show how a device senses the world, sends what it reads, and acts on it. This IoT education for schools stays practical from start to finish."],button:"Enquire About an IoT Workshop",altAction:{label:"See all workshops",to:"#other-workshops"},sections:[{heading:"What Students Build",body:"Groups build a small project that senses something and reacts to it.",items:["A circuit that reads a sensor","A device that responds when a value changes","A simple output students can see or hear","A test to check the reading is correct"]},{heading:"Sensors and Devices Used",body:"We work with everyday sensor types so students can connect the project to things they already know.",items:["Temperature and light sensors","Motion and distance sensors","Simple switches and buzzers","A board that connects the parts together"]},{heading:"Age Groups",body:"The build and the explanation change with the age of the group.",items:["Primary classes: guided builds with clear steps","Middle school: adding a second sensor and testing it","Senior school: open tasks with more student decisions"]}],photoSpots:[{label:"Real workshop photo needed",detail:"A student wiring a sensor during an IoT workshop. Use a photo from a real session, with the school's permission. Do not use a stock image here."}],faqs:[{q:"What is covered in an IoT workshop?",a:"Sensors, connected devices and a small working project. Students see how a device reads something and acts on it."},{q:"Which age groups can take part?",a:"Primary, middle and senior groups, with the build and the task matched to the age of the students."},{q:"Do students need to bring anything?",a:"No. We bring the materials for the session. If we need anything from the school — such as tables or power points — we tell you in advance."},{q:"How long is a session?",a:"The length is agreed with your institution when you enquire, based on the class groups and the time you have."},{q:"How do we book?",a:"Send your institution details through the enquiry page. A programme advisor will get back to you to plan the session."}],related:["P03"],keywords:["IoT Workshop for Schools","IoT Education for Schools"]},P07:{pageId:"P07",path:"/coding-workshops-schools",title:"Coding Workshops for Schools | Builds Your Mind",description:"Project-based coding workshops for school students. Learn programming by making real things. Contact us to plan a workshop for your school.",h1:"Coding Workshops for Schools",badge:"Learn by Making",intro:["Builds Your Mind runs project-based coding workshops for school students. Students learn programming by making real things, rather than working through exercises with no output.","A coding workshop for schools works best when there is something to show at the end. This coding education for schools is built around that idea."],button:"Enquire About a Coding Workshop",altAction:{label:"See all workshops",to:"#other-workshops"},sections:[{heading:"What Students Learn",body:"Students start with the basics and finish with a working project.",items:["Instructions, order and what happens when they are wrong","Repeating steps instead of writing them out again","Making a decision in code: if this, then that","Testing and fixing until it works"]},{heading:"Project Examples",body:"Every group works towards something they can run and show.",items:["A simple game or quiz","An animation with a clear sequence","A small tool that reacts to what the user enters","A project that controls something built by hand"]},{heading:"Age Groups",body:"The project and the explanation change with the age of the group.",items:["Primary classes: block-based coding with guided steps","Middle school: projects with their own rules and decisions","Senior school: text-based coding and open tasks"]},{heading:"Link with Robotics and IoT",body:"Coding is more convincing when it moves something. These sessions connect directly to our other workshops.",items:["Program the robot you build in a robotics workshop","Read a sensor and act on it in an IoT project","Take a project from the screen to something physical"]}],photoSpots:[{label:"Real workshop photo needed",detail:"Students working together on a coding project during a workshop. Use a photo from a real session, with the school's permission. Do not use a stock image here."}],faqs:[{q:"Do students need coding experience?",a:"No. Activities start from the basics, and the group works at a pace that suits the class."},{q:"Do you need a computer lab?",a:"For some sessions, yes. Tell us what your school has on the enquiry page and we will plan the session around it."},{q:"Which age groups can join?",a:"Primary, middle and senior groups, with the project and the tool matched to the age of the students."},{q:"Can coding be combined with robotics?",a:"Yes. Coding connects directly to our robotics and IoT workshops, so students can program something they have built."},{q:"How do we book a coding workshop?",a:"Send your institution details through the enquiry page. A programme advisor will get back to you to plan the session."}],related:["P03","P04","P06"],keywords:["Coding Workshop for Schools","Coding Education for Schools"]}},l=n,c=["P03","P04","P05","P06","P07"],u={P03:[{name:"School STEM Programme in Indore",path:"/school-stem-programme-indore"}],P04:[{name:"STEM Lab Setup & Programme for Schools in Indore",path:"/stem-lab-setup-schools-indore"},{name:"School STEM Programme in Indore",path:"/school-stem-programme-indore"}],P05:[{name:"School STEM Programme in Indore",path:"/school-stem-programme-indore"}],P06:[{name:"STEM Lab Setup & Programme for Schools in Indore",path:"/stem-lab-setup-schools-indore"},{name:"School STEM Programme in Indore",path:"/school-stem-programme-indore"}],P07:[]};export{h as S,u as a,l as b,c,d as w};
